design.css:
/* Blossom: Dantotsu's look (docs/theme-references/dantotsu-phone-parity.md). AMOLED black, the Pink
   seed, Poppins and 16 dp corners. Text metrics follow Dantotsu's Poppins v2 line boxes as the
   1080x2400 / 420 dpi emulator draws them: a 12 sp line is 20.19 dp, 14 sp 23.62 dp, 16 sp 26.67 dp.
   Icons are Material Symbols Rounded (Apache-2.0) masks. */

/* ---- Poster card (cards.poster and cards.continue: Continue Watching is a poster row in Dantotsu).
   item_media_compact.xml: a 102x154 cover with 16 dp corners, the score badge flush in the
   bottom-right corner (only its top-left corner rounded, 20 dp), the airing dot flush in the
   bottom-left corner, a 108 dp wide two-line title 6 dp under the cover and the "~ | 12" line. */
[data-part="blossom.cover"] { overflow: visible !important; }
[data-part="blossom.art"] { aspect-ratio: 102 / 154 !important; border-radius: 16px; background: #2a2c36; }
[data-part="blossom.score"] {
  gap: 0; margin: 0; padding: 0 6px 0 8px; border-radius: 20px 0 16px 0;
  background: #ffaed9; color: #610046;
}
[data-part="blossom.score-value"] { margin-left: 2px; padding: 0.2px 0 1.8px; font: 700 12px/20.19px var(--ui-font); letter-spacing: 0; }
[data-part="blossom.score-star"] {
  display: block; width: 12px; height: 12px; background: #610046;
  -webkit-mask: url(data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%20-960%20960%20960%22%3E%3Cpath%20d%3D%22M480-269%20314-169q-11%207-23%206t-21-8q-9-7-14-17.5t-2-23.5l44-189-147-127q-10-9-12.5-20.5T140-571q4-11%2012-18t22-9l194-17%2075-178q5-12%2015.5-18t21.5-6q11%200%2021.5%206t15.5%2018l75%20178%20194%2017q14%202%2022%209t12%2018q4%2011%201.5%2022.5T809-528L662-401l44%20189q3%2013-2%2023.5T690-171q-9%207-21%208t-23-6L480-269Z%22%2F%3E%3C%2Fsvg%3E) center / 12px 12px no-repeat; mask: url(data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%20-960%20960%20960%22%3E%3Cpath%20d%3D%22M480-269%20314-169q-11%207-23%206t-21-8q-9-7-14-17.5t-2-23.5l44-189-147-127q-10-9-12.5-20.5T140-571q4-11%2012-18t22-9l194-17%2075-178q5-12%2015.5-18t21.5-6q11%200%2021.5%206t15.5%2018l75%20178%20194%2017q14%202%2022%209t12%2018q4%2011%201.5%2022.5T809-528L662-401l44%20189q3%2013-2%2023.5T690-171q-9%207-21%208t-23-6L480-269Z%22%2F%3E%3C%2Fsvg%3E) center / 12px 12px no-repeat;
}
[data-part="blossom.airing"] { gap: 0; }
[data-part="blossom.ongoing"] { display: block; box-sizing: border-box; width: 16px; height: 16px; border: 2px solid #208358; border-radius: 8px; background: #6bf170; }
/* Dantotsu drops the line spacing only between lines: two lines are 41.5 dp, one is 23.6 dp. The small
   `top` offsets put the glyphs where Poppins v2 draws them on the device (measured against the emulator). */
[data-part="blossom.title"] { position: relative; top: 0.5px; margin: 6px -3px 4.17px; font: 400 14px/18.67px var(--ui-font); letter-spacing: 0; color: #eeeeee; }
[data-part="blossom.progress"] { position: relative; top: -1.4px; gap: 0; margin: 0 -3px 10px; white-space: pre; font: 400 14px/23.62px var(--ui-font); letter-spacing: 0; }
/* The text runs 3 dp past the cover on each side where the card is the reference's 102 dp; in grids
   that stretch the card to their cell (whose items clip their paint) it keeps to the cover. */
[data-slot="search.results"] :is([data-part="blossom.title"], [data-part="blossom.progress"]) { margin-inline: 0; }
[data-part="blossom.user"] { color: #dfbecd; }
[data-part="blossom.total"] { color: rgb(238 238 238 / 0.58); }

/* Continue Watching resolves its source on tap: the wait shows on the cover as a primary ring on a
   60 % veil (Dantotsu's ProgressBar colours) instead of izumi's white disc over the whole card. */
[data-family="continue"] > [data-part="card.overlay"][data-state="resolving"] {
  inset: 0 0 auto; aspect-ratio: 102 / 154; height: auto; border-radius: 16px; background: rgb(0 0 0 / 0.6);
}
[data-family="continue"] > [data-part="card.overlay"][data-state="resolving"] > span { width: 40px; height: 40px; background: none; color: #ffaed9; }
[data-family="continue"] > [data-part="card.overlay"][data-state="resolving"] svg { width: 40px; height: 40px; stroke-width: 2.5; }

/* ---- Rows (fragment_home.xml): a 42.67 dp heading with the title at x 32 and a 24 dp arrow in a
   40 dp box, then a 250 dp track whose first cover sits at x 26, 6 dp under the track top, 12 apart.
   Row pitch 292.67 dp. A 12 dp fade on the edges (FadingEdgeRecyclerView). */
[data-part="row.title"], [data-part="block.title"] { font-weight: 700; letter-spacing: 0; color: #eeeeee; }
@media (max-width: 640px) {
  [data-slot="row"] { margin-bottom: 0 !important; }
  [data-slot="row"] [data-part="row.header"] { align-items: center; min-height: 42.67px; margin: 0; padding: 8px 16px 8px 32px; }
  [data-slot="row"] [data-part="row.title"] { position: relative; top: 0.9px; font: 700 16px/26.67px var(--font-heading) !important; }
  [data-slot="row"] [data-part="row.more"] { width: 40px; height: 40px; margin: -6.67px 0; padding: 8px; color: #cac4d0; translate: 3.4px 0; }
  [data-slot="row"] [data-part="row.more"] > svg { display: none; }
  [data-slot="row"] [data-part="row.more"]::before {
    content: ""; display: block; width: 24px; height: 24px; background: currentColor;
    -webkit-mask: url(data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%20-960%20960%20960%22%3E%3Cpath%20d%3D%22M647-440H160v-80h487L423-744l57-56%20320%20320-320%20320-57-56%20224-224Z%22%2F%3E%3C%2Fsvg%3E) center / 24px 24px no-repeat; mask: url(data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%20-960%20960%20960%22%3E%3Cpath%20d%3D%22M647-440H160v-80h487L423-744l57-56%20320%20320-320%20320-57-56%20224-224Z%22%2F%3E%3C%2Fsvg%3E) center / 24px 24px no-repeat;
  }
  [data-slot="row"] [data-part="row.track"] {
    align-items: flex-start; min-height: 250px; padding: 6px 26px 0 !important; scroll-padding-inline: 26px;
    -webkit-mask-image: linear-gradient(to right, transparent, #000 12px, #000 calc(100% - 12px), transparent);
    mask-image: linear-gradient(to right, transparent, #000 12px, #000 calc(100% - 12px), transparent);
  }
  /* Home ends with Dantotsu's 128 dp spacer (izumi already reserves the bar's 88). */
  [data-slot="home"] { padding-bottom: 40px; }

  /* Continue Watching with nothing to continue (fragment_home.xml homeWatchingEmpty; design.json
     rows.byId.continue.empty "shown"): the row keeps its heading and its 250 dp track holds, centred,
     the 32 dp movie_filter glyph (colorControlNormal) and the 14 sp line, both at 0.58, then the
     128 dp filled M3 button 12 dp lower (4 dp insets, 24 dp padding, 16 dp corners), whose
     "Browse Anime" breaks onto two lines in its 80 dp. Dantotsu's wording; screen readers keep izumi's. */
  [data-slot="row"] [data-part="row.empty"] {
    flex: 0 0 calc(100% + 52px); box-sizing: border-box; height: 250px; min-height: 0; margin: -6px -26px 0; padding: 0;
    gap: 0; justify-content: center; align-items: center; border: 0; border-radius: 0; background: none;
  }
  [data-slot="row"] [data-part="row.empty"]::before {
    content: ""; flex: 0 0 32px; width: 32px; height: 32px; background: #d4c2c8; opacity: 0.58;
    -webkit-mask: url(data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%20-960%20960%20960%22%3E%3Cpath%20d%3D%22m342-362%2029%2062q3%206%209%206t9-6l29-62%2062-29q6-3%206-9t-6-9l-62-29-29-62q-3-6-9-6t-9%206l-29%2062-62%2029q-6%203-6%209t6%209l62%2029Zm252-52%2017%2035q3%206%209%206t9-6l17-35%2035-17q6-3%206-9t-6-9l-35-17-17-35q-3-6-9-6t-9%206l-17%2035-35%2017q-6%203-6%209t6%209l35%2017ZM160-800l65%20130q7%2014%2020%2022t28%208q30%200%2046-25.5t2-52.5l-41-82h80l65%20130q7%2014%2020%2022t28%208q30%200%2046-25.5t2-52.5l-41-82h80l65%20130q7%2014%2020%2022t28%208q30%200%2046-25.5t2-52.5l-41-82h120q33%200%2056.5%2023.5T880-720v480q0%2033-23.5%2056.5T800-160H160q-33%200-56.5-23.5T80-240v-480q0-33%2023.5-56.5T160-800Z%22%2F%3E%3C%2Fsvg%3E) center / 32px 32px no-repeat; mask: url(data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%20-960%20960%20960%22%3E%3Cpath%20d%3D%22m342-362%2029%2062q3%206%209%206t9-6l29-62%2062-29q6-3%206-9t-6-9l-62-29-29-62q-3-6-9-6t-9%206l-29%2062-62%2029q-6%203-6%209t6%209l62%2029Zm252-52%2017%2035q3%206%209%206t9-6l17-35%2035-17q6-3%206-9t-6-9l-35-17-17-35q-3-6-9-6t-9%206l-17%2035-35%2017q-6%203-6%209t6%209l35%2017ZM160-800l65%20130q7%2014%2020%2022t28%208q30%200%2046-25.5t2-52.5l-41-82h80l65%20130q7%2014%2020%2022t28%208q30%200%2046-25.5t2-52.5l-41-82h80l65%20130q7%2014%2020%2022t28%208q30%200%2046-25.5t2-52.5l-41-82h120q33%200%2056.5%2023.5T880-720v480q0%2033-23.5%2056.5T800-160H160q-33%200-56.5-23.5T80-240v-480q0-33%2023.5-56.5T160-800Z%22%2F%3E%3C%2Fsvg%3E) center / 32px 32px no-repeat;
  }
  [data-slot="row"] [data-part="row.empty.text"] { margin: 0; font-size: 0; line-height: 0; color: rgb(235 224 226 / 0.58); }
  [data-slot="row"] [data-part="row.empty.text"]::before { content: "All caught up, when New?" / ""; font: 400 14px/23.62px var(--ui-font); letter-spacing: 0; }
  [data-slot="row"] [data-part="row.empty.action"] {
    display: block; box-sizing: border-box; width: 128px; min-height: 40px; margin: 16px 0 4px; padding: 6px 24px;
    border-radius: 16px; background: #ffaed9; font-size: 0; line-height: 0; text-align: center; color: #610046;
  }
  [data-slot="row"] [data-part="row.empty.action"]::before { content: "Browse Anime" / ""; font: 500 14px/23.62px var(--ui-font); letter-spacing: 0.1px; }
}

/* ---- Bottom navigation (item_navbar.xml + AnimatedBottomBar defaults): a 240x56 pill 32 dp above the
   gesture inset, 6 dp padding, three 76 dp tabs. The active tab shows only its label (14 sp bold caps,
   primary) over a 20x3 tertiary bar 6 dp above the pill edge; the others show only a 24 dp filled
   glyph in colorOutline. It never hides on scroll. */
[data-slot="nav.bottom"] {
  width: calc(var(--nav-items, 3) * 76px + 12px); min-width: 0; height: 56px; padding: 6px !important; gap: 0 !important;
  bottom: calc(32px + env(safe-area-inset-bottom)) !important;
  box-shadow: 0 4px 8px rgb(0 0 0 / 0.16) !important;
}
/* Three tabs make Dantotsu's 240 dp pill (3 x 76 + the 6 dp padding each side); the bar publishes its
   destination count (--nav-items, Home included), so a bar with more destinations grows by 76 dp a tab. */
[data-slot="nav.bottom"] [data-part="nav.item"] { flex: 1 0 76px; width: 76px; height: 44px !important; padding: 0 !important; gap: 0; }
[data-slot="nav.bottom"] [data-part="nav.item.icon"] { width: 24px; height: 24px; padding: 0; }
[data-slot="nav.bottom"] [data-part="nav.item.icon"] > svg { display: none; }
[data-slot="nav.bottom"] [data-part="nav.item.icon"]::before {
  content: ""; display: block; width: 24px; height: 24px; background: currentColor;
  -webkit-mask: var(--blossom-glyph) center / 24px 24px no-repeat; mask: var(--blossom-glyph) center / 24px 24px no-repeat;
}
[data-slot="nav.bottom"] [data-part="nav.item"][data-active] [data-part="nav.item.icon"] { display: none; }
[data-slot="nav.bottom"] [data-part="nav.item.label"] { padding: 0 2px; font: 700 14px/23.62px var(--ui-font); letter-spacing: 0.27px; text-transform: uppercase; white-space: nowrap; }
[data-slot="nav.bottom"] [data-dest="search"] [data-part="nav.item.label"] { font-size: 0; line-height: 0; }
[data-slot="nav.bottom"] [data-dest="search"] [data-part="nav.item.label"]::before { content: "Anime" / ""; font-size: 14px; line-height: 23.62px; }
[data-slot="nav.bottom"] [data-part="nav.item"][data-active]::after {
  content: ""; position: absolute; bottom: 0; left: calc(50% - 10px); width: 20px; height: 3px; background: #f3ba9c;
}

/* Glyph per destination (people reorder destinations, so never by position). The left tab is
   Dantotsu's Anime tab (where it browses and searches), the right one its open-book tab. */
