/* ---- Home header (fragment_home.xml). Dantotsu has no app bar: the profile row sits on the user's
   banner. The izumi mark keeps its own size in a 48 dp strip at the top (the one geometric
   allowance, so everything below runs 16 dp lower than Dantotsu's), the banner and its fade run
   under the status bar, and the header icons become Dantotsu's 52 dp outlined circles at the
   profile row's right edge. Settings lies over the avatar: tapping the avatar opens settings, as
   in Dantotsu. Phones only. */
@keyframes blossom-ken-burns { from { transform: scale(1) translate(0, 0); } to { transform: scale(1.18) translate(-3%, -2%); } }
@media (max-width: 640px) and (prefers-reduced-motion: no-preference) {
  :scope:not(.a11y-reduce-motion) [data-slot="block.profile-header"] [data-part="block.banner"] { animation: blossom-ken-burns 25s ease-in-out infinite alternate; }
}
@media (max-width: 640px) {
  [data-slot="page"]:has([data-slot="block.profile-header"]) { --main-safe-top: 0px; }
  [data-slot="page"]:has([data-slot="block.profile-header"]) [data-slot="home.header"] {
    position: absolute; inset: 0 0 auto; z-index: 5; height: calc(48px + env(safe-area-inset-top));
    margin: 0; padding: env(safe-area-inset-top) 32px 0; pointer-events: none;
  }
  [data-slot="page"]:has([data-slot="block.profile-header"]) [data-slot="home.header"] > :has(> [data-part="home.header.actions"]) { height: 48px; }
  [data-slot="page"]:has([data-slot="block.profile-header"]) [data-slot="home.header"] > * > :not([data-part="home.header.actions"]) { pointer-events: auto; }
  [data-slot="page"]:has([data-slot="block.profile-header"]) [data-part="home.header.actions"] {
    position: absolute; top: calc(env(safe-area-inset-top) + 52px); right: 32px; flex-direction: row; gap: 10px; pointer-events: auto;
  }
  [data-part="home.header.action"] {
    width: 52px; height: 52px; margin: 0; border: 1px solid #49454f; border-radius: 26px; background: transparent !important; color: #eeeeee;
  }
  [data-part="home.header.action"] > svg { display: none; }
  [data-part="home.header.action"]::before {
    content: ""; display: block; width: 28.8px; height: 28.8px; background: currentColor;
    -webkit-mask: var(--blossom-glyph) center / contain no-repeat; mask: var(--blossom-glyph) center / contain no-repeat;
  }
  [data-part="home.header.action"][data-dest="search"] { --blossom-glyph: url(data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%20-960%20960%20960%22%3E%3Cpath%20d%3D%22M380-320q-109%200-184.5-75.5T120-580q0-109%2075.5-184.5T380-840q109%200%20184.5%2075.5T640-580q0%2044-14%2083t-38%2069l224%20224q11%2011%2011%2028t-11%2028q-11%2011-28%2011t-28-11L532-372q-30%2024-69%2038t-83%2014Zm0-80q75%200%20127.5-52.5T560-580q0-75-52.5-127.5T380-760q-75%200-127.5%2052.5T200-580q0%2075%2052.5%20127.5T380-400Z%22%2F%3E%3C%2Fsvg%3E); }
  /* Settings is the right-most circle; with a profile header it lies over the avatar (the avatar
     shows through; without a picture Dantotsu's 32 dp gear stands in). */
  [data-part="home.header.action"][data-dest="settings"] { order: 9; }
  [data-part="home.header.action"][data-dest="settings"]::before { width: 32px; height: 32px; }
  [data-slot="page"]:has([data-slot="block.profile-header"] img[data-part="block.avatar"]) [data-part="home.header.action"][data-dest="settings"] { border-color: transparent; }
  [data-slot="page"]:has([data-slot="block.profile-header"] img[data-part="block.avatar"]) [data-part="home.header.action"][data-dest="settings"]::before { visibility: hidden; }

  /* Banner 232 + S (216 + the brand strip), crisp, drifting; the fade runs from 94 dp above the
     page top to the block's end (linear_gradient_bg: #000 at the bottom, clear #1C1C1C at the top). */
  [data-slot="block.profile-header"] { margin: 0 !important; padding: 0 !important; }
  [data-slot="block.profile-header"] > :has(> [data-part="block.banner"]) { border-radius: 0; background: transparent; }
  [data-slot="block.profile-header"] [data-part="block.banner"] { inset: 0 0 auto; height: calc(232px + env(safe-area-inset-top)); transform-origin: 50% 0; }
  [data-slot="block.profile-header"] [data-part="block.scrim"] {
    inset: -94px 0 auto; height: calc(334px + env(safe-area-inset-top));
    background: linear-gradient(to top, #000, rgb(28 28 28 / 0)) !important;
  }
  /* Profile row: padding 32 (+16), min 64; name and stats left, the 52 dp outlined avatar right. */
  [data-slot="block.profile-header"] [data-part="block.profile"] {
    align-items: flex-start; gap: 0; min-height: calc(env(safe-area-inset-top) + 144px);
    padding: calc(env(safe-area-inset-top) + 48px) 32px 32px;
  }
  [data-slot="block.profile-header"] [data-part="block.avatar"] {
    order: 2; box-sizing: border-box; width: 52px; height: 52px; margin: 4px 0 0 10px;
    border: 1px solid #49454f !important; background: transparent;
  }
  [data-slot="block.profile-header"] span[data-part="block.avatar"] { font-size: 0; }
  [data-slot="block.profile-header"] [data-part="block.name"] { margin-bottom: -4px; font: 700 16px/26.67px var(--ui-font); letter-spacing: 0; color: #eeeeee; }
  [data-slot="block.profile-header"] [data-part="block.stat"] {
    display: flex !important; flex-direction: row-reverse; justify-content: flex-end; gap: 4px;
    font: 400 12px/20.19px var(--ui-font); letter-spacing: 0;
  }
  [data-slot="block.profile-header"] [data-part="block.stat"]::before { content: none !important; display: none; }
  [data-slot="block.profile-header"] [data-part="block.stat.label"] { color: rgb(238 238 238 / 0.58); text-transform: capitalize; }
  /* Dantotsu's wording for the first line ("Episodes Watched 26"). */
  [data-slot="block.profile-header"] [data-part="block.stat"][data-key="episodes"] [data-part="block.stat.label"] { font-size: 0; line-height: 0; }
  [data-slot="block.profile-header"] [data-part="block.stat"][data-key="episodes"] [data-part="block.stat.label"]::before { content: "Episodes Watched"; font-size: 12px; line-height: 20.19px; }
  [data-slot="block.profile-header"] [data-part="block.stat.value"] { font-weight: 700; color: #ffaed9; }

  /* Hub cards: 166x72 at x 32 / W-198, 16 dp corners, the 1 dp outlineVariant ring on the outlined
     card's black fill, a 16 sp bold caps label straight over a 64x2 primary bar. Anime List sits 4 dp
     lower than its neighbour (its 8 dp margins centre it in a 96 dp box), as in the app. */
  [data-slot="block.profile-header"] :has(> [data-part="button"]) {
    display: grid; grid-template-columns: repeat(2, minmax(0, 256px)); justify-content: space-between; align-items: start;
    gap: 16px; padding: 8px 32px 16px; background: none;
  }
  [data-slot="block.profile-header"] [data-part="button"][data-dest="library"] { margin: 4px 0 -4px; }
}
[data-slot="block.profile-header"] [data-part="button"] {
  position: relative; display: flex; flex-direction: column; align-items: center; justify-content: center;
  box-sizing: border-box; height: 72px; padding: 0 12px; border: 1px solid #49454f; border-radius: 16px;
  background: #000; backdrop-filter: none;
  font: 700 16px/26.67px var(--ui-font); letter-spacing: 0; text-align: center; text-transform: uppercase; white-space: nowrap; color: #eeeeee;
}
[data-slot="block.profile-header"] [data-part="button"]::after { content: ""; display: block; width: 64px; height: 2px; background: #ffaed9; }
/* Hub art (art: true): a banner from the viewer's own titles under 60 % black, label and bar on top. */
[data-slot="block.profile-header"] [data-part="button"] { overflow: hidden; }
[data-slot="block.profile-header"] [data-part="button"]::before { content: ""; position: absolute; inset: 0; z-index: 1; background: rgb(0 0 0 / 0.6); }
[data-slot="block.profile-header"] [data-part="button"]:not(:has([data-part="block.button.art"]))::before { content: none; }
[data-slot="block.profile-header"] [data-part="block.button.art"] { z-index: 0; }
[data-slot="block.profile-header"] [data-part="button"] > span { position: relative; z-index: 2; }
[data-slot="block.profile-header"] [data-part="button"]::after { position: relative; z-index: 2; }
[data-slot="block.profile-header"] [data-part="block.name"] { font-weight: 700; }

/* ---- Search (activity_search.xml + item_search_header.xml): an outlined 28 dp-round field at x 24
   (fill #000, 1 dp onSurface @0.38 ring, primary 2 dp when focused, 14 sp bold, the search glyph at
   the end), the 36 dp tonal filter buttons (#1C1C1C, 18 dp round, 13 sp bold primary), and results in
   screenWidth/120 columns with each 102 dp card 6 dp into its cell. Phones only. */
@media (max-width: 640px) {
  [data-part="search.filters"] > [data-part="search.field"] {
    box-sizing: border-box; width: calc(100% - 16px); height: 50.67px; margin: 13.33px 8px 0; padding: 0 48px 0 16px;
    border: 1px solid rgb(235 224 226 / 0.38); border-radius: 28px;
    background: #000 url(data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%20-960%20960%20960%22%3E%3Cpath%20fill%3D%22%23D4C2C8%22%20d%3D%22M380-320q-109%200-184.5-75.5T120-580q0-109%2075.5-184.5T380-840q109%200%20184.5%2075.5T640-580q0%2044-14%2083t-38%2069l224%20224q11%2011%2011%2028t-11%2028q-11%2011-28%2011t-28-11L532-372q-30%2024-69%2038t-83%2014Zm0-80q75%200%20127.5-52.5T560-580q0-75-52.5-127.5T380-760q-75%200-127.5%2052.5T200-580q0%2075%2052.5%20127.5T380-400Z%22%2F%3E%3C%2Fsvg%3E) right 12px center / 24px 24px no-repeat;
    font: 700 14px/23.62px var(--ui-font); letter-spacing: 0; color: #eeeeee;
  }
  [data-part="search.filters"] > [data-part="search.field"]:focus { border: 2px solid #ffaed9; padding-left: 15px; }
  [data-part="search.filters"] > [data-part="search.field"]::placeholder { color: #d4c2c8; opacity: 1; }
  [data-part="search.filters"] > :has([data-part="search.filter"]) { gap: 8px; padding-inline: 24px; }
  [data-part="search.filter"] {
    flex: 0 0 auto; height: 36px; min-height: 36px; padding: 0 12px; border: 0; border-radius: 18px;
    background: #1c1c1c; font: 700 13px/21.9px var(--ui-font); letter-spacing: 0; color: #ffaed9;
  }
  [data-part="search.filter"] :is(span, svg) { color: #ffaed9 !important; }
  [data-part="search.grid"] { column-gap: 0 !important; row-gap: 0 !important; }
  [data-slot="search.results"] [data-part="card"] { width: 102px !important; margin: 0 0 0 6px; padding-top: 6px; }
  [data-slot="search.results"] :is([data-part="blossom.title"], [data-part="blossom.progress"]) { margin-inline: -3px; }
}
/* ---- Loading rows (MediaAdaptor skeleton binding + skeleton_*.xml): a #2A2C36 102x154 cover with
   16 dp corners, a 108x12 title bar (6 dp corners) and a 54x8 #232530 stats bar, no shimmer.
   Continue Watching loads the same poster placeholders. */
@media (max-width: 640px) {
  [data-slot="row"] [data-part="row.skeleton"] {
    flex: 0 0 102px; width: 102px !important; height: 154px; aspect-ratio: auto !important; overflow: visible;
    border-radius: 16px; background: #2a2c36;
  }
  [data-slot="row"] [data-part="row.skeleton"]::before {
    inset: auto; left: -3px; top: 164px; width: 108px; height: 12px; transform: none; animation: none;
    border-radius: 6px; background: #2a2c36;
  }
  [data-slot="row"] [data-part="row.skeleton"]::after {
    content: ""; position: absolute; left: -3px; top: 184px; width: 54px; height: 8px; border-radius: 4px; background: #232530;
  }
}
/* ---- Motion (Functions.kt setSlideIn / setAnimation): cards slide in from their own width with a
   1.1 overshoot over 750 ms while fading in over 500 ms, each 25 % (187 ms) after the previous, and
   pop from scale 0 over 150 ms. Off under reduced motion. */
@keyframes blossom-slide-in { from { translate: 100% 0; } to { translate: 0 0; } }
@keyframes blossom-fade-in { from { opacity: 0; } to { opacity: 1; } }
@keyframes blossom-card-pop { from { scale: 0; } to { scale: 1; } }
@media (max-width: 640px) and (prefers-reduced-motion: no-preference) {
  :scope:not(.a11y-reduce-motion) [data-slot="row"] [data-part="row.track"] > :has(> [data-part="card"]) {
    animation: blossom-slide-in 750ms cubic-bezier(.3, 1.25, .6, 1) both, blossom-fade-in 500ms ease-in-out both, blossom-card-pop 150ms cubic-bezier(.3, 1.35, .6, 1) both;
  }
  :scope:not(.a11y-reduce-motion) [data-slot="row"] [data-part="row.track"] > :has(> [data-part="card"]):nth-child(2) { animation-delay: 187ms; }
  :scope:not(.a11y-reduce-motion) [data-slot="row"] [data-part="row.track"] > :has(> [data-part="card"]):nth-child(3) { animation-delay: 375ms; }
  :scope:not(.a11y-reduce-motion) [data-slot="row"] [data-part="row.track"] > :has(> [data-part="card"]):nth-child(4) { animation-delay: 562ms; }
  :scope:not(.a11y-reduce-motion) [data-slot="row"] [data-part="row.track"] > :has(> [data-part="card"]):nth-child(n+5) { animation-delay: 750ms; }
}

/* ============================================================================================
   Series page (activity_media.xml, fragment_media_info.xml, item_media_source.xml,
   item_episode_list.xml). Phone rules are scoped to [data-variant="phone"]; desktop keeps izumi's
   own series layout with the Blossom card, button and facts styling below.
   Geometry is in dp with the status bar inset S added where Dantotsu adds it: banner 384 + S, the
   108x160 cover 64 dp above the banner's end, the outlined list button flush with it, the 60 dp
   access row, and the Info / Watch content starting 64 dp under the banner.
   ============================================================================================ */

/* ---- Both layouts ----
   Bold text carries a little tracking: Dantotsu's Poppins Bold sets wider than izumi's at the same
   size (measured glyph runs on the emulator: "Sousou no Frieren" 150.1 vs 144.8 dp, "FINISHED" 64.8 vs
   61.7, "ADD TO LIST" 88.8 vs 84.2, "INFO" 33.1 vs 32.0), so each bold role gets the spacing that
   closes its own gap (caps more than mixed case; 16 sp caps such as the hub labels already match). */
[data-slot="detail"] [data-part="detail.poster"] { border-radius: 16px; }
[data-slot="detail"] [data-part="detail.alt-title"] { display: none; }
[data-part="detail.list-button"][data-variant="full"] {
  height: 48px; border: 1px solid #eeeeee; border-radius: 16px; background: transparent;
  font: 700 14px/23.62px var(--ui-font); letter-spacing: 0.55px; text-transform: uppercase; color: #dfbecd;
}
[data-slot="detail"][data-variant="desktop"] [data-part="detail.facts"][data-variant="table"] { max-width: 560px; }
[data-part="detail.facts"][data-variant="table"] [data-part="fact.label"] { font-weight: 500; color: rgb(238 238 238 / 0.58); }
[data-part="detail.facts"][data-variant="table"] [data-part="fact.value"] { font-weight: 700; text-align: end; color: #eeeeee; }
[data-part="detail.facts"][data-variant="table"] [data-part="fact"]:is([data-key="score"], [data-key="studio"], [data-key="author"]) [data-part="fact.value"] { color: #ffaed9; }
[data-part="detail.facts"][data-variant="table"] [data-part="fact.suffix"] { color: #eeeeee; }
[data-part="detail.facts"][data-variant="table"] [data-part="fact"]:is([data-key="status"], [data-key="format"], [data-key="season"]) [data-part="fact.value"] { text-transform: uppercase; }
