[data-slot="detail"][data-variant="phone"] [data-part="episode.download"]:is([data-state="queued"], [data-state="progress"]) { --blossom-glyph: url(data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%20-960%20960%20960%22%3E%3Cpath%20d%3D%22M160-160v-80h110l-16-14q-52-46-73-105t-21-119q0-111%2066.5-197.5T400-790v84q-72%2026-116%2088.5T240-478q0%2045%2017%2087.5t53%2078.5l10%2010v-98h80v240H160Zm400-10v-84q72-26%20116-88.5T720-482q0-45-17-87.5T650-648l-10-10v98h-80v-240h240v80H690l16%2014q49%2049%2071.5%20106.5T800-482q0%20111-66.5%20197.5T560-170Z%22%2F%3E%3C%2Fsvg%3E); }
[data-slot="detail"][data-variant="phone"] [data-part="episode.download"][data-state="done"] { --blossom-glyph: url(data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%20-960%20960%20960%22%3E%3Cpath%20d%3D%22m424-296%20282-282-56-56-226%20226-114-114-56%2056%20170%20170Zm56%20216q-83%200-156-31.5T197-197q-54-54-85.5-127T80-480q0-83%2031.5-156T197-763q54-54%20127-85.5T480-880q83%200%20156%2031.5T763-763q54%2054%2085.5%20127T880-480q0%2083-31.5%20156T763-197q-54%2054-127%2085.5T480-80Zm0-80q134%200%20227-93t93-227q0-134-93-227t-227-93q-134%200-227%2093t-93%20227q0%20134%2093%20227t227%2093Zm0-320Z%22%2F%3E%3C%2Fsvg%3E); }
[data-slot="detail"][data-variant="phone"] [data-part="episode.download"][data-state="progress"] > span {
  position: absolute; top: 40px; left: 0; right: 0; text-align: center; font: 700 10px/16.4px var(--ui-font); letter-spacing: 0; color: rgb(238 238 238 / 0.6);
}
[data-slot="detail"][data-variant="phone"] [data-part="episode.download"]:disabled { opacity: 0.38; }

/* Numbers layout = the reference's Compact: four columns of 64 dp tiles. */
[data-slot="detail"][data-variant="phone"] [data-slot="detail.episodes"] div:has(> [data-part="episode"][data-variant="number"]) {
  grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 16px;
}
[data-slot="detail"][data-variant="phone"] [data-part="episode"][data-variant="number"] { height: 64px; border-radius: 16px; font: 700 16px/26.67px var(--ui-font); }
[data-slot="detail"][data-variant="phone"] [data-part="episode"][data-variant="number"][data-filler] { background: rgb(255 107 8 / 0.16); }
[data-slot="detail"][data-variant="phone"] [data-part="episode"][data-variant="number"][data-state="watched"] { background: #1c1c1c; opacity: 0.6; }

/* ---- Motion: the Info / Watch swap zooms the page in from 1.3 (ZoomOutPageTransformer), the active
   tab's label and indicator pop in with the bar's overshoot; banners drift (Ken Burns). ---- */
@keyframes blossom-page-zoom { 0% { transform: scale(1.3); opacity: 0; } 61% { transform: scale(0.98); } 100% { transform: scale(1); opacity: 1; } }
@keyframes blossom-indicator { from { transform: scaleX(0); } to { transform: scaleX(1); } }
@keyframes blossom-tab-label { from { transform: translateY(20px); opacity: 0; } to { transform: none; opacity: 1; } }
@keyframes blossom-sync { to { rotate: -360deg; } }
@media (prefers-reduced-motion: no-preference) {
  :scope:not(.a11y-reduce-motion) [data-slot="detail"][data-variant="phone"] [data-slot="detail.banner"] [data-part="detail.backdrop"] {
    animation: blossom-ken-burns-banner 25s ease-in-out infinite alternate;
  }
  :scope:not(.a11y-reduce-motion) [data-slot="detail"][data-variant="phone"] :is(
    [data-part="detail.poster"], [data-part="detail.head"] > :not([data-part="detail.poster"]), [data-part="detail.buttons"],
    [data-part="detail.actions"] > :is([data-part="detail.lead"], [data-action="save"], [data-action="share"], [data-action="trailer"], [data-action="more"], [data-part="detail.menu"])
  ) { transition: translate 200ms ease-in-out; }
  /* Both tabs' bodies (izumi builds them anew on every switch). */
  :scope:not(.a11y-reduce-motion) [data-slot="detail"][data-variant="phone"] [data-part="tabs"] ~ * {
    transform-origin: 50% 0; animation: blossom-page-zoom 300ms ease-out;
  }
  :scope:not(.a11y-reduce-motion) [data-slot="detail"][data-variant="phone"] [data-part="tabs"][data-variant="bottom"] [data-part="tab"][data-active] { animation: blossom-tab-label 400ms cubic-bezier(.3, 1.35, .6, 1); }
  :scope:not(.a11y-reduce-motion) [data-slot="detail"][data-variant="phone"] [data-part="tabs"][data-variant="bottom"] [data-part="tab"][data-active]::before { animation: blossom-indicator 400ms cubic-bezier(.3, 1.35, .6, 1); }
  /* The sync glyph turns while the episode is queued or downloading (EpisodeAdapters startOrContinueRotation). */
  :scope:not(.a11y-reduce-motion) [data-slot="detail"][data-variant="phone"] [data-part="episode.download"]:is([data-state="queued"], [data-state="progress"])::before { animation: blossom-sync 1s linear infinite; }
  @supports (animation-timeline: scroll()) {
    :scope:not(.a11y-reduce-motion) [data-slot="detail"][data-variant="phone"] [data-slot="detail.banner"] [data-part="detail.backdrop"] {
      animation: blossom-ken-burns-banner 25s ease-in-out infinite alternate, blossom-parallax linear both;
      animation-timeline: auto, scroll(root); animation-range: normal, 0px 384px;
    }
    :scope:not(.a11y-reduce-motion) [data-slot="detail"][data-variant="phone"] [data-part="detail.bar.title"] {
      animation: blossom-strip-title linear both, blossom-title-in 200ms ease-in-out both;
      animation-timeline: scroll(root), auto; animation-range: 0px 384px, normal;
    }
  }
}

/* ---- Loading (MediaDetailsActivity + fragment_media_info.xml mediaInfoProgressBar): the header is drawn
   at once from the tapped card (banner, cover, title, status, list button, totals) and the tab's body
   is the platform's indeterminate ring (a 40 dp ring in a 48 dp box) in colorPrimary, 32 dp under the content top, until the record
   arrives. ---- */
@keyframes blossom-spin { to { transform: rotate(360deg); } }
[data-slot="detail"][data-variant="phone"][data-pending] [data-part="detail.content"] > :has(> [data-part="tabs"]) > :not([data-part="tabs"]) { display: none; }
[data-slot="detail"][data-variant="phone"][data-pending] [data-part="detail.content"] > :has(> [data-part="tabs"])::after {
  content: ""; display: block; box-sizing: border-box; width: 40px; height: 40px; margin: 36px auto;
  border: 3.5px solid #ffaed9; border-right-color: transparent; border-bottom-color: transparent; border-radius: 50%;
  animation: blossom-spin 1s linear infinite;
}
